183	    /**
184	     * Normalize an email to its canonical stored form, which is lower-cased. This is the single
185	     * source of truth for how an email is persisted, so inputs that differ only in letter case
186	     * are stored identically. Applied by {@link #setEmail(String)} so every persistence path
187	     * (create and update, mapper or hand-copied) stores the same canonical value.
188	     *
189	     * @param email the raw email, possibly {@code null}
190	     * @return the lower-cased form, or {@code null} if the input was {@code null}
191	     */
192	    public static String normalizeEmail(String email) {
193	        return email == null ? null : email.toLowerCase();
194	    }
195	
196	    /**
197	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
198	     * truth for how a telephone is compared and persisted, so inputs that differ only in
199	     * formatting (spaces, dashes, brackets) are treated as the same number.
200	     *
201	     * <p>The rules are:
202	     * <ul>
203	     *   <li>spaces, dashes and brackets are stripped;</li>
204	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
205	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
206	     *       is dropped from the national digits;</li>
207	     *   <li>the result must have 8 to 15 digits after the {@code '+'};</li>
208	     *   <li>for a recognized country code the national number (the digits after the country
209	     *       code) must have the length that code requires: {@code '+61'} requires 9 national
210	     *       digits and {@code '+1'} requires 10.</li>
211	     * </ul>
212	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
213	     * values are returned unchanged.
214	     *
215	     * @param telephone the raw telephone, possibly {@code null}
216	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
217	     *     valid E.164 number
218	     */
219	    public static String normalizeTelephone(String telephone) {
220	        if (telephone == null) {
221	            return null;
222	        }
223	        String trimmed = telephone.trim();
224	        boolean hasCountryCode = trimmed.startsWith("+");
225	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
226	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
227	        if (hasCountryCode) {
228	            stripped = stripped.substring(1);
229	        }
230	        if (!stripped.matches("\\d+")) {
231	            return null;
232	        }
233	        String digits;
234	        if (hasCountryCode) {
235	            digits = stripped;
236	        } else {
237	            if (stripped.startsWith("0")) {
238	                stripped = stripped.substring(1);
239	            }
240	            digits = "61" + stripped;
241	        }
242	        if (digits.length() < 8 || digits.length() > 15) {
243	            return null;
244	        }
245	        if (!hasValidNationalNumberLength(digits)) {
246	            return null;
247	        }
248	        return "+" + digits;
249	    }
250	
251	    /**
252	     * Format a stored E.164 telephone for human display: the country code, a space, then the
253	     * national digits grouped left-to-right in blocks of three separated by spaces (e.g.
254	     * {@code "+61412345678"} becomes {@code "+61 412 345 678"}). The country code is identified
255	     * from the recognized {@link #NATIONAL_NUMBER_LENGTHS} table (longest prefix first); when no
256	     * recognized country code matches, the digits after the {@code '+'} are grouped in threes with
257	     * no separate country-code segment. This is a display-only transform; the raw E.164 value is
258	     * kept unchanged elsewhere.
259	     *
260	     * @param telephone the stored E.164 telephone, possibly {@code null}
261	     * @return the human-formatted telephone, or {@code null} when the input is {@code null}; an
262	     *     input that is not a well-formed E.164 number ({@code '+'} followed by digits) is returned
263	     *     unchanged
264	     */
265	    public static String telephoneDisplay(String telephone) {
266	        if (telephone == null) {
267	            return null;
268	        }
269	        if (!telephone.matches("\\+\\d+")) {
270	            return telephone;
271	        }
272	        String digits = telephone.substring(1);
273	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
274	            if (digits.startsWith(countryCode)) {
275	                return "+" + countryCode + " " + groupDigits(digits.substring(countryCode.length()));
276	            }
277	        }
278	        return "+" + groupDigits(digits);
279	    }
280	
281	    /**
282	     * Group a run of digits left-to-right into blocks of three separated by single spaces, with a
283	     * trailing block of one or two digits when the length is not a multiple of three (e.g.
284	     * {@code "412345678"} becomes {@code "412 345 678"}).
285	     *
286	     * @param digits the national digits
287	     * @return the space-grouped digits
288	     */
289	    private static String groupDigits(String digits) {
290	        StringBuilder grouped = new StringBuilder(digits.length() + digits.length() / 3);
291	        for (int i = 0; i < digits.length(); i++) {
292	            if (i > 0 && i % 3 == 0) {
293	                grouped.append(' ');
294	            }
295	            grouped.append(digits.charAt(i));
296	        }
297	        return grouped.toString();
298	    }
299	
300	    /**
301	     * Required national-number length (the count of digits after the country code) for each
302	     * recognized country code, longest country code first so the prefix match is unambiguous.
303	     */
304	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = new LinkedHashMap<>();
305	    static {
306	        NATIONAL_NUMBER_LENGTHS.put("61", 9);
307	        NATIONAL_NUMBER_LENGTHS.put("1", 10);
308	    }
309	
310	    /**
311	     * Check that the national number of an E.164 digit string (no leading {@code '+'}) has the
312	     * length its country code requires. A country code with no registered length places no
313	     * additional constraint and is accepted.
314	     *
315	     * @param digits the E.164 digits without the leading {@code '+'}
316	     * @return {@code true} if the national-number length is valid for the country code
317	     */
318	    private static boolean hasValidNationalNumberLength(String digits) {
319	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
320	            String countryCode = entry.getKey();
321	            if (digits.startsWith(countryCode)) {
322	                return digits.length() - countryCode.length() == entry.getValue();
323	            }
324	        }
325	        return true;
326	    }
327	
328	    /**
329	     * Common street-type abbreviations expanded by {@link #normalizeAddress(String)}, keyed by the
330	     * upper-cased abbreviation.
331	     */
332	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
333	        "ST", "STREET",
334	        "RD", "ROAD",
335	        "AVE", "AVENUE");
336	
337	    /**
338	     * Normalize an address to its canonical stored form. Leading and trailing whitespace is
339	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
340	     * and common street-type abbreviations are expanded as whole words ({@code ST}->{@code STREET},
341	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). This is the single source of truth for
342	     * how an address is persisted and compared, so inputs that differ only in letter case, spacing
343	     * or abbreviation are treated as the same address. Applied by {@link #setAddress(String)} so
344	     * every persistence path (create and update, mapper or hand-copied) stores the same canonical
345	     * value. The transform is idempotent: a normalized address normalizes to itself.
346	     *
347	     * @param address the raw address, possibly {@code null}
348	     * @return the normalized form, or {@code null} if the input was {@code null}
349	     */
350	    public static String normalizeAddress(String address) {
351	        if (address == null) {
352	            return null;
353	        }
354	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
355	        if (collapsed.isEmpty()) {
356	            return collapsed;
357	        }
358	        String[] tokens = collapsed.split(" ");
359	        StringBuilder normalized = new StringBuilder(collapsed.length());
360	        for (int i = 0; i < tokens.length; i++) {
361	            if (i > 0) {
362	                normalized.append(' ');
363	            }
364	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
365	        }
366	        return normalized.toString();
367	    }
368	
369	    /**
370	     * Normalize a household field (such as last name or address) to its canonical form for
371	     * duplicate-household comparison. Leading and trailing whitespace is trimmed, internal runs
372	     * of whitespace are collapsed to a single space, and the result is lower-cased, so inputs
373	     * that differ only in letter case or spacing are treated as the same value.
374	     *
375	     * @param value the raw field value, possibly {@code null}
376	     * @return the normalized form, or {@code null} if the input was {@code null}
377	     */
378	    public static String normalizeHousehold(String value) {
379	        if (value == null) {
380	            return null;
381	        }
382	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
383	    }
384	
385	    /**
386	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
387	     * last name (compared case-insensitively with collapsed whitespace, see
388	     * {@link #normalizeHousehold(String)}) and the same postcode. The value is deterministic in
389	     * those two fields, so two owners who share a last name and postcode are assigned the same id
390	     * automatically. It is formatted {@code 'HH-<HEX12>'} where {@code HEX12} is the first twelve
391	     * upper-cased hex characters of the SHA-256 digest of
392	     * {@code normalizedLastName + '|' + postcode}.
393	     *
394	     * @param lastName the owner's last name, possibly {@code null}
395	     * @param postcode the owner's postcode, possibly {@code null}
396	     * @return the household id, or {@code null} if either field is {@code null}
397	     */
398	    public static String householdId(String lastName, String postcode) {
399	        String normalizedLastName = normalizeHousehold(lastName);
400	        if (normalizedLastName == null || postcode == null) {
401	            return null;
402	        }
403	        String key = normalizedLastName + "|" + postcode;
404	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase();
405	    }
406	
407	    /**
408	     * Compute the full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. This is the
409	     * shared primitive behind every hash-derived owner value (the household id and the customer code),
410	     * so they all agree on algorithm and encoding.
411	     *
412	     * @param value the string to digest, never {@code null}
413	     * @return the 64-character lower-case hex digest
414	     */
415	    private static String sha256Hex(String value) {
416	        try {
417	            byte[] digest = MessageDigest.getInstance("SHA-256")
418	                .digest(value.getBytes(StandardCharsets.UTF_8));
419	            StringBuilder hex = new StringBuilder(digest.length * 2);
420	            for (byte b : digest) {
421	                hex.append(String.format("%02x", b));
422	            }
423	            return hex.toString();
424	        } catch (NoSuchAlgorithmException e) {
425	            // SHA-256 is a standard algorithm required to be present on every JVM.
426	            throw new IllegalStateException("SHA-256 not available", e);
427	        }
428	    }
429	
430	    /**
431	     * Build an owner's {@code customerCode}, the stable owner identity assigned once when the owner is
432	     * created. It is formatted {@code '<REGION>-<HASH8>'} where:
433	     * <ul>
434	     *   <li>{@code REGION} is the region code derived from the postcode (see
435	     *       {@link #regionForPostcode(String)}), or {@code 'UNKNOWN'} when the postcode is absent or
436	     *       in no known range, and</li>
437	     *   <li>{@code HASH8} is the first eight upper-cased hex characters of the SHA-256 digest of the
438	     *       normalized telephone (see {@link #normalizeTelephone(String)}) concatenated with the last
439	     *       name.</li>
440	     * </ul>
441	     * The value is deterministic in the postcode, telephone and last name (e.g.
442	     * {@code 'NSW-1A2B3C4D'}); it carries no sequence number.
443	     *
444	     * @param postcode the owner's postcode, possibly {@code null}
445	     * @param telephone the owner's raw telephone, possibly {@code null}
446	     * @param lastName the owner's last name, possibly {@code null}
447	     * @return the customer code, or {@code null} if the telephone or last name is {@code null}
448	     */
449	    public static String customerCode(String postcode, String telephone, String lastName) {
450	        if (telephone == null || lastName == null) {
451	            return null;
452	        }
453	        String region = regionForPostcode(postcode);
454	        if (region == null) {
455	            region = "UNKNOWN";
456	        }
457	        String normalizedTelephone = normalizeTelephone(telephone);
458	        String key = (normalizedTelephone == null ? "" : normalizedTelephone) + lastName;
459	        return region + "-" + sha256Hex(key).substring(0, 8).toUpperCase();
460	    }
461	
462	    /**
463	     * Compute an owner's {@code identityKey}, the single derived value through which all
464	     * duplicate detection is now expressed. It consolidates the three formerly separate
465	     * telephone, email and household duplicate checks into one key, formatted as
466	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}:
467	     * <ul>
468	     *   <li>the normalized telephone (see {@link #normalizeTelephone(String)}),</li>
469	     *   <li>the normalized email (see {@link #normalizeEmail(String)}), or the empty string
470	     *       when no email is present, and</li>
471	     *   <li>the household id (see {@link #householdId(String, String)}).</li>
472	     * </ul>
473	     * A {@code null} component is rendered as the empty string. Two owners are the same identity
474	     * only when their <em>whole</em> keys are equal; because the telephone is part of the key, two
475	     * members of the same household with different telephones have different keys.
476	     *
477	     * @param telephone the owner's raw telephone, possibly {@code null}
478	     * @param email the owner's email, possibly {@code null}
479	     * @param lastName the owner's last name, possibly {@code null}
480	     * @param postcode the owner's postcode, possibly {@code null}
481	     * @return the identity key, never {@code null}
482	     */
483	    public static String identityKey(String telephone, String email, String lastName, String postcode) {
484	        String normalizedTelephone = normalizeTelephone(telephone);
485	        String normalizedEmail = normalizeEmail(email);
486	        String household = householdId(lastName, postcode);
487	        return (normalizedTelephone == null ? "" : normalizedTelephone)
488	            + "|" + (normalizedEmail == null ? "" : normalizedEmail)
489	            + "|" + (household == null ? "" : household);
490	    }
491	
492	    /**
493	     * Build an owner's {@code membershipNumber}, the stable membership identifier derived from the
494	     * owner's own persisted fields. It is formatted {@code '<customerCode>-M<YY>'} where {@code YY}
495	     * is the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}). The
496	     * value is deterministic in those two fields.
497	     *
498	     * @param customerCode the owner's customer code, possibly {@code null}
499	     * @param registrationDate the owner's registration date, possibly {@code null}
500	     * @return the membership number, or {@code null} if either field is {@code null}
501	     */
502	    public static String membershipNumber(String customerCode, LocalDate registrationDate) {
503	        if (customerCode == null || registrationDate == null) {
504	            return null;
505	        }
506	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
507	    }
508	
509	    /**
510	     * Build an owner's {@code membershipLevel}, the derived numeric level assigned on create. The
511	     * value starts at 1, gains 1 when an email is present and gains 1 when {@code namesakeCount} is 0,
512	     * and is capped at 3 (level 4 is reserved for tenure). The value is deterministic in those two
513	     * fields.
514	     *
515	     * @param namesakeCount the owner's namesake count, possibly {@code null}
516	     * @param email the owner's email, possibly {@code null}
517	     * @return the membership level, an integer from 1 to 3
518	     */
519	    public static int membershipLevel(Integer namesakeCount, String email) {
520	        int level = 1;
521	        if (email != null && !email.isEmpty()) {
522	            level++;
523	        }
524	        if (namesakeCount != null && namesakeCount == 0) {
525	            level++;
526	        }
527	        return Math.min(level, 3);
528	    }
529	
530	    /**
531	     * Fixed city-to-region table used by {@link #regionForCity(String)} to resolve a city's region
532	     * for postcode validation, keyed by the exact city name.
533	     */
534	    private static final Map<String, String> CITY_REGION = Map.of(
535	        "Sydney", "NSW",
536	        "Melbourne", "VIC",
537	        "Brisbane", "QLD");
538	
539	    /**
540	     * Derive an owner's {@code locality}, the canonical region for the owner, from the {@code REGION}
541	     * segment of the owner's {@code customerCode} (see {@link #customerCode(String, String, String)}).
542	     * Because the customer code's region is itself derived from the postcode, the locality now shares
543	     * the owner's region-and-hash identity: it is the text before the first {@code '-'} of the customer
544	     * code. When the owner has no customer code the locality is {@code 'UNKNOWN'}.
545	     *
546	     * @param customerCode the owner's customer code, possibly {@code null}
547	     * @return the canonical region string, or {@code 'UNKNOWN'} when no customer code is present
548	     */
549	    public static String locality(String customerCode) {
550	        if (customerCode == null) {
551	            return "UNKNOWN";
552	        }
553	        int dash = customerCode.indexOf('-');
554	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
555	    }
556	
557	    /**
558	     * Resolve the canonical region for a city from the fixed {@link #CITY_REGION} table. A city not
559	     * in the table (including {@code null}) resolves to {@code 'UNKNOWN'}.
560	     *
561	     * @param city the owner's city, possibly {@code null}
562	     * @return the matching region, or {@code 'UNKNOWN'} when the city is not in the table
563	     */
564	    private static String regionForCity(String city) {
565	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
566	    }
567	
568	    /**
569	     * Fixed region-to-postcode-range table used by {@link #isPostcodeValidForCity(String, String)}
570	     * and {@link #regionForPostcode(String)}, keyed by the canonical region. Each entry is the
571	     * inclusive low and high bound of the region's valid 4-digit postcodes
572	     * ({@code NSW} 2000-2099, {@code VIC} 3000-3099, {@code QLD} 4000-4099). A region not in this
573	     * table (including {@code 'UNKNOWN'}) places no range constraint.
574	     */
575	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
576	        "NSW", new int[] {2000, 2099},
577	        "VIC", new int[] {3000, 3099},
578	        "QLD", new int[] {4000, 4099});
579	
580	    /**
581	     * Resolve the canonical region whose postcode range contains the given postcode, using the fixed
582	     * {@link #REGION_POSTCODE_RANGES} table. A {@code null} postcode, one that is not exactly four
583	     * digits, or one that falls in no known range resolves to {@code null}.
584	     *
585	     * @param postcode the owner's postcode, possibly {@code null}
586	     * @return the matching region, or {@code null} when no range contains the postcode
587	     */
588	    private static String regionForPostcode(String postcode) {
589	        if (postcode == null || !postcode.matches("\\d{4}")) {
590	            return null;
591	        }
592	        int value = Integer.parseInt(postcode);
593	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
594	            int[] range = entry.getValue();
595	            if (value >= range[0] && value <= range[1]) {
596	                return entry.getKey();
597	            }
598	        }
599	        return null;
600	    }
601	
602	    /**
603	     * Check whether a postcode is valid for an owner's city. Postcode is optional, so a
604	     * {@code null} or empty postcode is always valid. When present it must be exactly four
605	     * digits, and when the city's region (from the fixed city-to-region table) has a known postcode
606	     * range the value must fall within that inclusive range. A city with no known region accepts
607	     * any four-digit postcode. This is the single source of
608	     * truth for postcode validity, shared by the DTO validation and any persistence path.
609	     *
610	     * @param postcode the owner's postcode, possibly {@code null}
611	     * @param city the owner's city, possibly {@code null}
612	     * @return {@code true} if the postcode is absent or valid for the city, {@code false} otherwise
613	     */
614	    public static boolean isPostcodeValidForCity(String postcode, String city) {
615	        if (postcode == null || postcode.isEmpty()) {
616	            return true;
617	        }
618	        if (!postcode.matches("\\d{4}")) {
619	            return false;
620	        }
621	        int[] range = REGION_POSTCODE_RANGES.get(regionForCity(city));
622	        if (range == null) {
623	            return true;
624	        }
625	        int value = Integer.parseInt(postcode);
626	        return value >= range[0] && value <= range[1];
627	    }
628	
629	    /**
630	     * Compute an owner's {@code checkDigit}, a single Luhn check digit (0-9) over the digits
631	     * contained in the {@code customerCode}. Non-digit characters in the code are ignored. The
632	     * value is deterministic in the customer code and is the standard Luhn check digit: each
633	     * digit is weighted right-to-left, every second digit (starting with the rightmost) is
634	     * doubled with digit sums above nine reduced by nine, and the check digit is the amount that
635	     * brings the weighted sum up to the next multiple of ten.
636	     *
637	     * @param customerCode the owner's customer code, possibly {@code null}
638	     * @return the Luhn check digit from 0 to 9, or {@code null} if the customer code is {@code null}
639	     */
640	    public static Integer checkDigit(String customerCode) {
641	        if (customerCode == null) {
642	            return null;
643	        }
644	        int sum = 0;
645	        boolean dbl = true;
646	        for (int i = customerCode.length() - 1; i >= 0; i--) {
647	            char c = customerCode.charAt(i);
648	            if (c < '0' || c > '9') {
649	                continue;
650	            }
651	            int d = c - '0';
652	            if (dbl) {
653	                d *= 2;
654	                if (d > 9) {
655	                    d -= 9;
656	                }
657	            }
658	            sum += d;
659	            dbl = !dbl;
660	        }
661	        return (10 - (sum % 10)) % 10;
662	    }
663	
664	    /**
665	     * Derive an owner's {@code contactPreference}, the preferred channel for contacting the owner.
666	     * The value is {@code 'EMAIL'} when an email is present and {@code 'PHONE'} otherwise. The value
667	     * is deterministic in the email.
668	     *
669	     * @param email the owner's email, possibly {@code null}
670	     * @return {@code 'EMAIL'} when an email is present, otherwise {@code 'PHONE'}
671	     */
672	    public static String contactPreference(String email) {
673	        return (email != null && !email.isEmpty()) ? "EMAIL" : "PHONE";
674	    }
675	
676	    /**
677	     * Derive an owner's {@code ageBand}, the band the owner's age falls into on the registration
678	     * date. The age in whole years is the number of completed years between {@code birthDate} and
679	     * {@code registrationDate}, and the band is {@code 'MINOR'} when under 18, {@code 'ADULT'} when
680	     * 18 to 64 inclusive, and {@code 'SENIOR'} when 65 or older. The value is deterministic in those
681	     * two fields and is only defined when both are present.
682	     *
683	     * @param birthDate the owner's date of birth, possibly {@code null}
684	     * @param registrationDate the owner's registration date, possibly {@code null}
685	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when either date
686	     *     is {@code null}
687	     */
688	    public static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
689	        if (birthDate == null || registrationDate == null) {
690	            return null;
691	        }
692	        int age = Period.between(birthDate, registrationDate).getYears();
693	        if (age < 18) {
694	            return "MINOR";
695	        }
696	        if (age < 65) {
697	            return "ADULT";
698	        }
699	        return "SENIOR";
700	    }
701	
702	    protected Set<Pet> getPetsInternal() {
703	        if (this.pets == null) {
704	            this.pets = new HashSet<>();
705	        }
706	        return this.pets;
707	    }
708	
709	    protected void setPetsInternal(Set<Pet> pets) {
710	        this.pets = pets;
711	    }
712	
713	    public List<Pet> getPets() {
714	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
715	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
716	        return Collections.unmodifiableList(sortedPets);
717	    }
718	
719	    public void setPets(List<Pet> pets) {
720	        this.pets = new HashSet<>(pets);
721	    }
722	
723	    public void addPet(Pet pet) {
724	        getPetsInternal().add(pet);
725	        pet.setOwner(this);
726	    }
727	
728	    /**
729	     * Return the Pet with the given name, or null if none found for this Owner.
730	     *
731	     * @param name to test
732	     * @return true if pet name is already in use
733	     */
734	    public Pet getPet(String name) {
735	        return getPet(name, false);
736	    }
737	
738	    /**
739	     * Return the Pet with the given name, or null if none found for this Owner.
740	     *
741	     * @param name to test
742	     * @return true if pet name is already in use
743	     */
744	    public Pet getPet(String name, boolean ignoreNew) {
745	        name = name.toLowerCase();
746	        for (Pet pet : getPetsInternal()) {
747	            if (!ignoreNew || !pet.isNew()) {
748	                String compName = pet.getName();
749	                compName = compName.toLowerCase();
750	                if (compName.equals(name)) {
751	                    return pet;
752	                }
753	            }
754	        }
755	        return null;
756	    }
757	
758	    public Pet getPet(Integer petId) {
759	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
760	    }
761	
762	    @Override
763	    public String toString() {
764	        return new ToStringCreator(this)
765	
766	            .append("id", this.getId())
767	            .append("new", this.isNew())
768	            .append("lastName", this.getLastName())
769	            .append("firstName", this.getFirstName())
770	            .append("address", this.address)
771	            .append("city", this.city)
772	            .append("telephone", this.telephone)
773	            .toString();
774	    }
775	}
